CREATE OR REPLACE FUNCTION public.camera_review_token_info(p_token uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('valid',EXISTS(SELECT 1 FROM product_review_requests r WHERE r.token=p_token AND r.consumed_at IS NULL AND public.camera_order_delivered(r.order_id)),'product_id',(SELECT r.product_id FROM product_review_requests r WHERE r.token=p_token)); $$;